import {
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial
} from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, DirectionalLight, AmbientLight, Color } = ctx.THREE;

  // Root Container
  const container = new Group();

  // 1. Stage Backdrop (W-PCP / Design Doctrine)
  // To avoid FLAT_VOID, we build a grounded dark backdrop plane behind the card
  const backdropGeo = new PlaneGeometry(10, 8);
  const backdropMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    roughness: 0.8,
    metalness: 0.1
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  container.add(backdrop);

  // 2. Card Group (This will receive hover/click effects)
  const cardGroup = new Group();
  container.add(cardGroup);

  // Card Body (Box for 3D depth and beveled feel)
  const cardWidth = 2.4;
  const cardHeight = 3.2;
  const cardDepth = 0.1;
  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color('#0b0b10'),
    roughness: 0.5,
    metalness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.1
  });
  const cardBody = new Mesh(cardGeo, cardMat);
  cardBody.position.set(0, 0, 0);
  cardGroup.add(cardBody);

  // Accent Edge Indicator (Visual Spec: "accent edge on focus / hover")
  const edgeGeo = new PlaneGeometry(cardWidth + 0.04, cardHeight + 0.04);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'), // default state subtle paper
    transparent: true,
    opacity: 0.3
  });
  const borderMesh = new Mesh(edgeGeo, edgeMat);
  borderMesh.position.set(0, 0, -0.06);
  cardGroup.add(borderMesh);

  // Caption Strip at the bottom of the card
  const stripHeight = 0.55;
  const stripGeo = new PlaneGeometry(cardWidth - 0.16, stripHeight);
  const stripMat = new MeshStandardNodeMaterial({
    color: new Color('#16161d'),
    roughness: 0.7,
    metalness: 0.2
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardHeight / 2 + stripHeight / 2 + 0.08, 0.051);
  cardGroup.add(strip);

  // Caption text (using ctx.fontAtlas)
  const labelText = ctx.fontAtlas.createText('CALIBRE.01 // ATELIER', {
    fontSize: 10,
    color: '#e8ecf2',
    align: 'center'
  });
  labelText.position.set(0, -cardHeight / 2 + stripHeight / 2 + 0.08, 0.06);
  labelText.scale.setScalar(0.012);
  cardGroup.add(labelText);

  // 3. Load & Mount Mesh inside Card Center
  let loadedMesh = null;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedMesh = gltf.scene;

      // Fit and scale loaded mesh
      loadedMesh.scale.setScalar(0.75);
      loadedMesh.position.set(0, 0.3, 0.1);

      // Apply physical properties inline with Spec
      loadedMesh.traverse((child) => {
        if (child.isMesh) {
          child.material = new MeshPhysicalNodeMaterial({
            color: new Color('#e8ecf2'),
            roughness: 0.25,
            metalness: 0.9,
            clearcoat: 0.25
          });
        }
      });
      cardGroup.add(loadedMesh);
    }).catch(err => {
      console.warn("Failed to load gear GLB mesh", err);
    });
  }

  // 4. Local Lights (Design Doctrine: Dynamic product-shot lighting)
  const keyLight = new DirectionalLight('#ffffff', 1.2);
  keyLight.position.set(2, 3, 2.5);
  container.add(keyLight);

  const accentRim = new DirectionalLight('#ff2a38', 1.0); // Hue of the signal red accent
  accentRim.position.set(-2.5, -2, 1.5);
  container.add(accentRim);

  const fillLight = new AmbientLight('#0b0b10', 0.8);
  container.add(fillLight);

  // 5. Build Timelines & Interaction Loop
  const hoverTl = gsap.timeline({ paused: true });
  // Dynamic rise-in behavior: moves card up on Y and forward on Z slightly, highlighting edge
  hoverTl.to(cardGroup.position, {
    y: 0.15,
    z: 0.12,
    duration: 0.4,
    ease: 'power3.out'
  }, 0);
  hoverTl.to(edgeMat.color, {
    r: 1, g: 0.16, b: 0.22, // Transition visual edge indicator into accent signal red
    duration: 0.3
  }, 0);
  hoverTl.to(edgeMat, {
    opacity: 0.95,
    duration: 0.3
  }, 0);

  // Setup Interaction Handlers (userData.handlers)
  container.userData.handlers = {
    pointerover: () => {
      hoverTl.play();
    },
    pointerout: () => {
      hoverTl.reverse();
    },
    pointerdown: () => {
      // Press-down animation on click (scale settle)
      gsap.to(cardGroup.scale, {
        x: 0.96,
        y: 0.96,
        z: 0.96,
        duration: 0.12,
        ease: 'power2.out'
      });
    },
    pointerup: () => {
      gsap.to(cardGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.4,
        ease: 'back.out(1.7)'
      });
      // Emit trigger
      ctx.emit('hub-home.select', { id: 'thumbnail-gear' });
    }
  };

  // 6. Cleanup
  container.userData.cleanup = () => {
    hoverTl.kill();
    cardMat.dispose();
    cardGeo.dispose();
    edgeMat.dispose();
    edgeGeo.dispose();
    stripMat.dispose();
    stripGeo.dispose();
    backdropMat.dispose();
    backdropGeo.dispose();
  };

  return container;
}
